CREATE TABLE "${primehrSchema}".succession_career_family (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_succ_family_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".succession_career_family_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,family_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),legal_basis VARCHAR(2000) NOT NULL,pathway_guidance VARCHAR(4000) NOT NULL,links_revision INTEGER NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_family_root FOREIGN KEY(family_id) REFERENCES "${primehrSchema}".succession_career_family(id),CONSTRAINT fk_succ_family_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".succession_career_family_version(id),CONSTRAINT uk_succ_family_version UNIQUE(agency_id,family_id,definition_version),CONSTRAINT ck_succ_family_values CHECK(definition_version>=1 AND links_revision>=0),CONSTRAINT ck_succ_family_status CHECK(status IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_succ_family_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from));
CREATE INDEX ix_succ_family_effective ON "${primehrSchema}".succession_career_family_version(agency_id,status,effective_from,effective_to);
CREATE TABLE "${primehrSchema}".succession_career_path_link (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,family_version_id VARCHAR(36) NOT NULL,source_target_type VARCHAR(20) NOT NULL,source_target_id BIGINT NOT NULL,source_job_position_id BIGINT NOT NULL,source_position_name VARCHAR(250) NOT NULL,source_plantilla_id BIGINT,source_plantilla_name VARCHAR(250),source_fingerprint VARCHAR(120) NOT NULL,source_fetched_at TIMESTAMP WITH TIME ZONE NOT NULL,target_target_type VARCHAR(20) NOT NULL,target_target_id BIGINT NOT NULL,target_job_position_id BIGINT NOT NULL,target_position_name VARCHAR(250) NOT NULL,target_plantilla_id BIGINT,target_plantilla_name VARCHAR(250),target_fingerprint VARCHAR(120) NOT NULL,target_fetched_at TIMESTAMP WITH TIME ZONE NOT NULL,relationship_type VARCHAR(30) NOT NULL,development_guidance VARCHAR(4000) NOT NULL,display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_path_family FOREIGN KEY(family_version_id) REFERENCES "${primehrSchema}".succession_career_family_version(id),CONSTRAINT uk_succ_path_link UNIQUE(agency_id,family_version_id,source_target_type,source_target_id,target_target_type,target_target_id,relationship_type),CONSTRAINT ck_succ_path_types CHECK(source_target_type IN('JOB_POSITION','PLANTILLA') AND target_target_type IN('JOB_POSITION','PLANTILLA')),CONSTRAINT ck_succ_path_relationship CHECK(relationship_type IN('VERTICAL','LATERAL','DEVELOPMENTAL')),CONSTRAINT ck_succ_path_values CHECK(display_order>=1 AND NOT(source_target_type=target_target_type AND source_target_id=target_target_id)));
CREATE INDEX ix_succ_path_family ON "${primehrSchema}".succession_career_path_link(agency_id,family_version_id,display_order);
CREATE TABLE "${primehrSchema}".succession_criticality_framework (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_succ_criticality_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".succession_criticality_framework_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),legal_basis VARCHAR(2000) NOT NULL,decision_guidance VARCHAR(4000) NOT NULL,criteria_revision INTEGER NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_criticality_root FOREIGN KEY(framework_id) REFERENCES "${primehrSchema}".succession_criticality_framework(id),CONSTRAINT fk_succ_criticality_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".succession_criticality_framework_version(id),CONSTRAINT uk_succ_criticality_version UNIQUE(agency_id,framework_id,definition_version),CONSTRAINT ck_succ_criticality_values CHECK(definition_version>=1 AND criteria_revision>=0),CONSTRAINT ck_succ_criticality_status CHECK(status IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_succ_criticality_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from));
CREATE INDEX ix_succ_criticality_effective ON "${primehrSchema}".succession_criticality_framework_version(agency_id,status,effective_from,effective_to);
CREATE TABLE "${primehrSchema}".succession_criticality_criterion (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,label VARCHAR(200) NOT NULL,description VARCHAR(2000) NOT NULL,evidence_guidance VARCHAR(4000) NOT NULL,display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_criterion_framework FOREIGN KEY(framework_version_id) REFERENCES "${primehrSchema}".succession_criticality_framework_version(id),CONSTRAINT uk_succ_criterion_code UNIQUE(agency_id,framework_version_id,normalized_code),CONSTRAINT uk_succ_criterion_order UNIQUE(agency_id,framework_version_id,display_order),CONSTRAINT ck_succ_criterion_order CHECK(display_order>=1));
CREATE INDEX ix_succ_criterion_framework ON "${primehrSchema}".succession_criticality_criterion(agency_id,framework_version_id,display_order);
CREATE TABLE "${primehrSchema}".succession_critical_position_designation (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,target_type VARCHAR(20) NOT NULL,target_id BIGINT NOT NULL,job_position_id BIGINT NOT NULL,position_name VARCHAR(250) NOT NULL,plantilla_id BIGINT,plantilla_name VARCHAR(250),source_fingerprint VARCHAR(120) NOT NULL,source_fetched_at TIMESTAMP WITH TIME ZONE NOT NULL,framework_version_id VARCHAR(36) NOT NULL,framework_definition_version INTEGER NOT NULL,framework_fingerprint VARCHAR(120) NOT NULL,charter_version_id VARCHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,justification VARCHAR(4000) NOT NULL,assessment_date DATE NOT NULL,effective_from DATE,effective_to DATE,review_date DATE NOT NULL,status VARCHAR(20) NOT NULL,submitted_by VARCHAR(100),submitted_at TIMESTAMP WITH TIME ZONE,decision_by VARCHAR(100),decision_at TIMESTAMP WITH TIME ZONE,decision_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_designation_framework FOREIGN KEY(framework_version_id) REFERENCES "${primehrSchema}".succession_criticality_framework_version(id),CONSTRAINT fk_succ_designation_charter FOREIGN KEY(charter_version_id) REFERENCES "${primehrSchema}".succession_committee_charter_version(id),CONSTRAINT ck_succ_designation_type CHECK(target_type IN('JOB_POSITION','PLANTILLA')),CONSTRAINT ck_succ_designation_status CHECK(status IN('DRAFT','SUBMITTED','APPROVED','REJECTED','RETIRED')),CONSTRAINT ck_succ_designation_dates CHECK(review_date>=assessment_date AND (effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from)),CONSTRAINT ck_succ_designation_lifecycle CHECK((status='DRAFT' AND submitted_at IS NULL AND decision_at IS NULL) OR (status='SUBMITTED' AND submitted_at IS NOT NULL AND decision_at IS NULL) OR (status IN('APPROVED','REJECTED','RETIRED') AND submitted_at IS NOT NULL AND decision_at IS NOT NULL)));
CREATE INDEX ix_succ_designation_target ON "${primehrSchema}".succession_critical_position_designation(agency_id,target_type,target_id,status);
CREATE INDEX ix_succ_designation_committee ON "${primehrSchema}".succession_critical_position_designation(agency_id,charter_version_id,status);
CREATE TABLE "${primehrSchema}".succession_criticality_finding (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,designation_id VARCHAR(36) NOT NULL,criterion_id VARCHAR(36) NOT NULL,criterion_code VARCHAR(80) NOT NULL,criterion_label VARCHAR(200) NOT NULL,outcome VARCHAR(30) NOT NULL,reason VARCHAR(2000) NOT NULL,evidence_reference VARCHAR(1000),display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_finding_designation FOREIGN KEY(designation_id) REFERENCES "${primehrSchema}".succession_critical_position_designation(id),CONSTRAINT fk_succ_finding_criterion FOREIGN KEY(criterion_id) REFERENCES "${primehrSchema}".succession_criticality_criterion(id),CONSTRAINT uk_succ_finding_criterion UNIQUE(agency_id,designation_id,criterion_id),CONSTRAINT ck_succ_finding_outcome CHECK(outcome IN('MET','NOT_MET','NOT_APPLICABLE')),CONSTRAINT ck_succ_finding_order CHECK(display_order>=1));
CREATE INDEX ix_succ_finding_designation ON "${primehrSchema}".succession_criticality_finding(agency_id,designation_id,display_order);
